import { CopyButton, CopyButtonLabel } from "@/registry/erbium/blocks/copy-button";
import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup, ButtonGroupSeparator } from "@/registry/erbium/ui/button-group";

export default function ButtonGroupSeparatorDemo() {
  return (
    <ButtonGroup>
      <CopyButton value="Erbium UI" variant="secondary" size="sm">
        <CopyButtonLabel />
      </CopyButton>
      <ButtonGroupSeparator />
      <Button variant="secondary" size="sm">
        Paste
      </Button>
    </ButtonGroup>
  );
}

import ExampleButtonGroupSeparator from "../examples/button-group-separator";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleButtonGroupSeparator />
  </div>
);

export default Example;
